-- ~keep Oracle schema for the users_orders live-nullability profile.
--
-- Uses native `GENERATED BY DEFAULT AS IDENTITY` columns (Oracle 12c+)
-- instead of the legacy sequence+trigger autoincrement pattern, so this
-- file is self-contained: `Executor::seed_schema` applying this text is
-- the whole schema. There is no external sequence/trigger setup this file
-- depends on -- every committed fixture's seed data supplies explicit `id`
-- values anyway, so the identity default only matters for future fixtures
-- that omit them.

CREATE TABLE users (
id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
name VARCHAR2(255) NOT NULL,
email VARCHAR2(255),
status VARCHAR2(20) DEFAULT 'active' NOT NULL CHECK (status IN ('active', 'inactive', 'banned')),
created_at DATE DEFAULT SYSDATE NOT NULL
);

CREATE TABLE orders (
id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
user_id NUMBER NOT NULL,
total NUMBER(10, 2) NOT NULL,
notes CLOB,
created_at DATE DEFAULT SYSDATE NOT NULL,
CONSTRAINT fk_orders_users FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE tags (
id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
name VARCHAR2(255) NOT NULL UNIQUE
);

CREATE TABLE user_tags (
user_id NUMBER NOT NULL,
tag_id NUMBER NOT NULL,
PRIMARY KEY (user_id, tag_id),
CONSTRAINT fk_user_tags_users FOREIGN KEY (user_id) REFERENCES users (id),
CONSTRAINT fk_user_tags_tags FOREIGN KEY (tag_id) REFERENCES tags (id)
);
